class _CurrencyListPageState extends State<CurrencyListPage>
    with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  late Future<List<CurrencyModel>> _currencyListFuture;

  List<CurrencyModel> _allCurrencies = [];

  int _currentPage = 0;
  bool _hasMore = false;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _initAnimation();
    _loadCurrencies();
  }

  @override
  void dispose() {
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    WidgetsBinding.instance.removeObserver(this);
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: Duration(milliseconds: 400),
      vsync: this,
    );
  }

  Future<void> _loadCurrencies({int page = 0, String base = 'USD'}) async {
    final currencyRepository = context.read<CurrencyRepository>();

    _currencyListFuture =
        currencyRepository.fetchRates(CurrencyPageRequest(base: base, page: page)).then((CurrencyPage currencyPage) {
      final List<CurrencyModel> value = currencyPage.items;
      setState(() {
        _currentPage = currencyPage.page;
        _hasMore = currencyPage.hasMore;
      });
      _allCurrencies = value;

      if (_filteredCurrenciesNotifier.value.isEmpty) {
        _filteredCurrenciesNotifier.value = value;
      } else {
        final updatedList = List<CurrencyModel>.from(_filteredCurrenciesNotifier.value)..addAll(value);
        _filteredCurrenciesNotifier.value = updatedList;
      }

      _fadeController.forward(); // запускаем анимацию

      currencyRepository.saveCurrencyList(value);

      return value;
    });
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _filteredCurrenciesNotifier.value = result.toList(growable: false);
  }

  void _onShowMorePressed() {
    if (!_hasMore) return;
    final int nextPage = _currentPage + 1;
    _loadCurrencies(page: nextPage, base: 'USD');
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed && mounted) {
      _loadCurrencies(base: 'USD');
    }
  }

  @override
  Widget build(BuildContext context) {
    final S loc = context.loc;

    return Scaffold(
      appBar: AppBar(title: Text(loc.currencyRate)),
      body: Column(
        children: [
          Padding(
            padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
            child: SearchView(onChanged: _filterCurrencies),
          ),
          Expanded(
            child: FutureBuilder<List<CurrencyModel>>(
              future: _currencyListFuture,
              builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
                final List<CurrencyModel>? data = snapshot.data;
                if (data == null) return const SizedBox.shrink();

                return FadeTransition(
                  opacity: _fadeController.view,
                  child: ListView.builder(
                    itemCount: data.length + (_hasMore ? 1 : 0),
                    itemBuilder: (BuildContext context, int index) {
                      if (index == data.length) {
                        return Padding(
                          padding: const EdgeInsets.only(top: 20),
                          child: Center(
                            child: OutlinedButton(
                              onPressed: _onShowMorePressed,
                              child: Text(loc.showMore),
                            ),
                          ),
                        );
                      }

                      final CurrencyModel currency = data[index];

                      return Padding(
                        key: ValueKey(currency.id),
                        padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                        child: CurrencyCard(model: currency),
                      );
                    },
                    padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                  ),
                );
              },
            ),
          ),
        ],
      ),
    );
  }
}

